def-struct-hyp(
    Type.annotation(@$\lt$, Rl(T@Order.ctxt.T, T@Order.ctxt.T)), 
    Order.partial(T@Order.ctxt.T, $\lt$),
    struct(
        Logic.forall-typed(@t, T@Order.ctxt.T, Logic.neg(Rl.apply($\lt$, t, t))),
        Logic.forall-typed(@q, T@Order.ctxt.T, Logic.forall-typed(@r, T@Order.ctxt.T, Logic.forall-typed(@s, T@Order.ctxt.T, Logic.implies(Logic.and(Rl.apply($\lt$, q, r), Rl.apply($\lt$, r, s)), Rl.apply($\lt$, q, s)))))
    )
)
